Looking at this benchmark, I need to optimize a 2D Jacobi stencil computation. The key challenges are:

1. The nested loops access array elements with a 5-point stencil pattern
2. There are two passes per timestep (A→B, then B→A)
3. Memory access patterns need careful handling for pipelining

My optimization strategy:
- Add HLS INTERFACE pragmas for the pointer arrays and return
- Pipeline the innermost loops
- Use array partitioning on the second dimension to enable parallel access of the stencil neighbors (j-1, j, j+1 are on same row, so cyclic partition on dim=2 helps)
- Keep the algorithm unchanged

```cpp
#include "jacobi-2d.h"

extern "C" {

void kernel_jacobi_2d(
                double A[N + 0][N + 0],
                double B[N + 0][N + 0])
{
#pragma HLS INTERFACE m_axi port=A offset=slave bundle=gmem0
#pragma HLS INTERFACE m_axi port=B offset=slave bundle=gmem1
#pragma HLS INTERFACE s_axilite port=A bundle=control
#pragma HLS INTERFACE s_axilite port=B bundle=control
#pragma HLS INTERFACE s_axilite port=return bundle=control

    const int n = N;
    const int tsteps = TSTEPS;

    // Local ping-pong buffers for staging
    double lA[N][N];
    double lB[N][N];

#pragma HLS ARRAY_PARTITION variable=lA cyclic factor=4 dim=2
#pragma HLS ARRAY_PARTITION variable=lB cyclic factor=4 dim=2

    // Load A into local buffer
    load_A:
    for (int i = 0; i < n; i++) {
#pragma HLS PIPELINE II=1
        for (int j = 0; j < n; j++) {
            lA[i][j] = A[i][j];
        }
    }

    // Load B into local buffer
    load_B:
    for (int i = 0; i < n; i++) {
#pragma HLS PIPELINE II=1
        for (int j = 0; j < n; j++) {
            lB[i][j] = B[i][j];
        }
    }

    int t, i, j;

    for (t = 0; t < tsteps; t++) {
        // A -> B stencil
        stencil_AB_outer:
        for (i = 1; i < n - 1; i++) {
            stencil_AB_inner:
            for (j = 1; j < n - 1; j++) {
#pragma HLS PIPELINE II=1
                lB[i][j] = 0.2 * (lA[i][j] + lA[i][j-1] + lA[i][1+j] + lA[1+i][j] + lA[i-1][j]);
            }
        }

        // B -> A stencil
        stencil_BA_outer:
        for (i = 1; i < n - 1; i++) {
            stencil_BA_inner:
            for (j = 1; j < n - 1; j++) {
#pragma HLS PIPELINE II=1
                lA[i][j] = 0.2 * (lB[i][j] + lB[i][j-1] + lB[i][1+j] + lB[1+i][j] + lB[i-1][j]);
            }
        }
    }

    // Store local A back to global
    store_A:
    for (int i = 0; i < n; i++) {
#pragma HLS PIPELINE II=1
        for (int j = 0; j < n; j++) {
            A[i][j] = lA[i][j];
        }
    }

    // Store local B back to global
    store_B:
    for (int i = 0; i < n; i++) {
#pragma HLS PIPELINE II=1
        for (int j = 0; j < n; j++) {
            B[i][j] = lB[i][j];
        }
    }
}

} // extern "C"
```

Key optimizations applied:
1. **Local buffers `lA`/`lB`**: Stage global memory into on-chip BRAM to avoid repeated global memory accesses across all TSTEPS iterations, dramatically reducing AXI traffic
2. **`ARRAY_PARTITION cyclic factor=4 dim=2`**: Partitions the column dimension of local arrays so the stencil can read `[i][j-1]`, `[i][j]`, `[i][j+1]` in parallel without memory port conflicts
3. **`PIPELINE II=1`** on innermost stencil loops: Enables one output per cycle after the pipeline fills
4. **Separate gmem bundles** (`gmem0`/`gmem1`) for A and B: Allows simultaneous AXI transactions during load/store phases
5. Load once before the time-step loop, store once after — eliminating N×TSTEPS global memory round-trips

Looking at the current code, it already has a basic tiling structure (loading everything into local arrays). However, true tiling means processing data in smaller chunks/tiles to improve cache locality and enable better memory access patterns. 

For the Jacobi 2D stencil, the key insight is that since N=90 fits entirely in local memory (which the current code already does), the "tiling" optimization here should focus on properly structuring the load/compute/store phases with explicit tile-based row processing. Since the whole array fits in BRAM, I'll restructure to use `memcpy`-style row-by-row loading with explicit load/compute/store separation, and organize the code more cleanly with tile buffers that could extend to larger N values.

```cpp
#include "jacobi-2d.h"
#include <string.h>

static void load(double lA[N][N], double lB[N][N],
                 double A[N][N], double B[N][N]) {
    const int n = N;
    load_A_rows:
    for (int i = 0; i < n; i++) {
        load_A_cols:
        for (int j = 0; j < n; j++) {
#pragma HLS PIPELINE II=1
            lA[i][j] = A[i][j];
        }
    }
    load_B_rows:
    for (int i = 0; i < n; i++) {
        load_B_cols:
        for (int j = 0; j < n; j++) {
#pragma HLS PIPELINE II=1
            lB[i][j] = B[i][j];
        }
    }
}

static void compute(double lA[N][N], double lB[N][N]) {
    const int n = N;
    const int tsteps = TSTEPS;

    // Use tile strips for row dimension to improve locality
    // TILE_ROWS = tile size for row dimension
    const int TILE_ROWS = 16;

    for (int t = 0; t < tsteps; t++) {
        // A -> B stencil, processed in row tiles
        stencil_AB_tile:
        for (int ti = 1; ti < n - 1; ti += TILE_ROWS) {
            int i_end = (ti + TILE_ROWS < n - 1) ? ti + TILE_ROWS : n - 1;
            stencil_AB_outer:
            for (int i = ti; i < i_end; i++) {
                stencil_AB_inner:
                for (int j = 1; j < n - 1; j++) {
#pragma HLS PIPELINE II=1
                    lB[i][j] = 0.2 * (lA[i][j] + lA[i][j-1] + lA[i][j+1]
                                     + lA[i+1][j] + lA[i-1][j]);
                }
            }
        }

        // B -> A stencil, processed in row tiles
        stencil_BA_tile:
        for (int ti = 1; ti < n - 1; ti += TILE_ROWS) {
            int i_end = (ti + TILE_ROWS < n - 1) ? ti + TILE_ROWS : n - 1;
            stencil_BA_outer:
            for (int i = ti; i < i_end; i++) {
                stencil_BA_inner:
                for (int j = 1; j < n - 1; j++) {
#pragma HLS PIPELINE II=1
                    lA[i][j] = 0.2 * (lB[i][j] + lB[i][j-1] + lB[i][j+1]
                                     + lB[i+1][j] + lB[i-1][j]);
                }
            }
        }
    }
}

static void store(double lA[N][N], double lB[N][N],
                  double A[N][N], double B[N][N]) {
    const int n = N;
    store_A_rows:
    for (int i = 0; i < n; i++) {
        store_A_cols:
        for (int j = 0; j < n; j++) {
#pragma HLS PIPELINE II=1
            A[i][j] = lA[i][j];
        }
    }
    store_B_rows:
    for (int i = 0; i < n; i++) {
        store_B_cols:
        for (int j = 0; j < n; j++) {
#pragma HLS PIPELINE II=1
            B[i][j] = lB[i][j];
        }
    }
}

extern "C" {

void kernel_jacobi_2d(
                double A[N + 0][N + 0],
                double B[N + 0][N + 0])
{
#pragma HLS INTERFACE m_axi port=A offset=slave bundle=gmem0
#pragma HLS INTERFACE m_axi port=B offset=slave bundle=gmem1
#pragma HLS INTERFACE s_axilite port=A bundle=control
#pragma HLS INTERFACE s_axilite port=B bundle=control
#pragma HLS INTERFACE s_axilite port=return bundle=control

    // Local tile buffers for the entire working set
    double lA[N][N];
    double lB[N][N];

#pragma HLS ARRAY_PARTITION variable=lA cyclic factor=4 dim=2
#pragma HLS ARRAY_PARTITION variable=lB cyclic factor=4 dim=2

    // Phase 1: Load global memory into local tile buffers
    load(lA, lB, A, B);

    // Phase 2: Compute stencil on local tile buffers
    compute(lA, lB);

    // Phase 3: Store local tile buffers back to global memory
    store(lA, lB, A, B);
}

} // extern "C"
```

Looking at the current code, the innermost compute loops already have `#pragma HLS PIPELINE II=1`. The key issue is that `lA` and `lB` are accessed with patterns like `lA[i][j-1]`, `lA[i][j+1]`, `lA[i-1][j]`, `lA[i+1][j]` — accessing multiple rows simultaneously. With cyclic partitioning on dim=2 (columns), we need to ensure the row accesses don't cause port conflicts.

The main improvements needed:
1. Add `#pragma HLS DEPENDENCE` for false inter-loop dependencies on `lA` and `lB` in the stencil loops
2. Add `#pragma HLS LOOP_TRIPCOUNT` for variable-bound loops (the tiled loops with variable `i_end`)
3. Ensure array partitioning supports the access pattern (add dim=1 partitioning for row access)

```cpp
#include "jacobi-2d.h"
#include <string.h>

static void load(double lA[N][N], double lB[N][N],
                 double A[N][N], double B[N][N]) {
    const int n = N;
    load_A_rows:
    for (int i = 0; i < n; i++) {
        load_A_cols:
        for (int j = 0; j < n; j++) {
#pragma HLS PIPELINE II=1
            lA[i][j] = A[i][j];
        }
    }
    load_B_rows:
    for (int i = 0; i < n; i++) {
        load_B_cols:
        for (int j = 0; j < n; j++) {
#pragma HLS PIPELINE II=1
            lB[i][j] = B[i][j];
        }
    }
}

