Looking at the current code, I can see:

1. The inner loops (`stencil_AB_inner`, `stencil_BA_inner`) are already pipelined with II=1
2. The arrays `lA` and `lB` are partitioned with factor=4 on dim=2
3. The j-dimension loop iterates over columns, which is the natural unroll candidate since iterations are independent (stencil reads neighbors but with DEPENDENCE false pragma)

The strategy is to unroll the inner j-loops by factor=4 (matching the existing partition factor) to process 4 columns in parallel, and increase the partition factor to 8 for more parallelism while keeping resource growth reasonable.

Note: Since the stencil accesses `j-1`, `j`, `j+1`, unrolling requires careful consideration. With cyclic partitioning factor=8, we need to ensure port availability. I'll increase unroll to factor=4 matching the current partition, then bump partition to 8 for headroom.

```cpp
#include "jacobi-2d.h"
#include <string.h>

static void load(double lA[N][N], double lB[N][N],
                 double A[N][N], double B[N][N]) {
    const int n = N;
    load_A_rows:
    for (int i = 0; i < n; i++) {
        load_A_cols:
        for (int j = 0; j < n; j++) {
#pragma HLS PIPELINE II=1
            lA[i][j] = A[i][j];
        }
    }
    load_B_rows:
    for (int i = 0; i < n; i++) {
        load_B_cols:
        for (int j = 0; j < n; j++) {
#pragma HLS PIPELINE II=1
            lB[i][j] = B[i][j];
        }
    }
}

static void compute(double lA[N][N], double lB[N][N]) {
    const int n = N;
    const int tsteps = TSTEPS;

    const int TILE_ROWS = 16;

    for (int t = 0; t < tsteps; t++) {
        // A -> B stencil, processed in row tiles
        stencil_AB_tile:
        for (int ti = 1; ti < n - 1; ti += TILE_ROWS) {
#pragma HLS LOOP_TRIPCOUNT min=6 max=6
            int i_end = (ti + TILE_ROWS < n - 1) ? ti + TILE_ROWS : n - 1;
            stencil_AB_outer:
            for (int i = ti; i < i_end; i++) {
#pragma HLS LOOP_TRIPCOUNT min=1 max=16
                stencil_AB_inner:
                for (int j = 1; j < n - 1; j++) {
#pragma HLS PIPELINE II=1
#pragma HLS UNROLL factor=4
#pragma HLS DEPENDENCE variable=lA inter false
#pragma HLS DEPENDENCE variable=lB inter false
#pragma HLS LOOP_TRIPCOUNT min=88 max=88
                    lB[i][j] = 0.2 * (lA[i][j] + lA[i][j-1] + lA[i][j+1]
                                     + lA[i+1][j] + lA[i-1][j]);
                }
            }
        }

        // B -> A stencil, processed in row tiles
        stencil_BA_tile:
        for (int ti = 1; ti < n - 1; ti += TILE_ROWS) {
#pragma HLS LOOP_TRIPCOUNT min=6 max=6
            int i_end = (ti + TILE_ROWS < n - 1) ? ti + TILE_ROWS : n - 1;
            stencil_BA_outer:
            for (int i = ti; i < i_end; i++) {
#pragma HLS LOOP_TRIPCOUNT min=1 max=16
                stencil_BA_inner:
                for (int j = 1; j < n - 1; j++) {
#pragma HLS PIPELINE II=1
#pragma HLS UNROLL factor=4
#pragma HLS DEPENDENCE variable=lB inter false
#pragma HLS DEPENDENCE variable=lA inter false
#pragma HLS LOOP_TRIPCOUNT min=88 max=88
