    }
}

static void store(double lA[N][N], double lB[N][N],
                  double A[N][N], double B[N][N]) {
    const int n = N;
    store_A_rows:
    for (int i = 0; i < n; i++) {
        store_A_cols:
        for (int j = 0; j < n; j++) {
#pragma HLS PIPELINE II=1
            A[i][j] = lA[i][j];
        }
    }
    store_B_rows:
    for (int i = 0; i < n; i++) {
        store_B_cols:
        for (int j = 0; j < n; j++) {
