**Key changes made:**

1. **Added `#pragma HLS UNROLL factor=4`** to both `stencil_AB_inner` and `stencil_BA_inner` loops — these are the hot compute loops with independent iterations (confirmed by the existing `DEPENDENCE inter false` pragmas)

2. **Increased array partition factor from 4 to 8** on dim=2 for both `lA` and `lB` — the stencil accesses `j-1`, `j`, and `j+1`, so with unroll factor=4, up to 12 simultaneous accesses can occur; factor=8 provides enough banks to avoid port conflicts and support the parallel reads

Looking at the current code, I need to apply double buffering. However, this is a special case: the computation operates on the **entire** A and B arrays (not chunked tiles), so there's only one "tile" of work. 

The meaningful double buffering here is to overlap the **store** of results back to global memory with the next hypothetical iteration, but since there's only one call, the real benefit comes from structuring the code to use ping-pong buffers in preparation for future tiling, OR we can double-buffer the load/store phases.

In this case, I'll apply double buffering by creating two sets of buffers (ping-pong) so that the **load** of data can conceptually overlap with **compute** and **store** phases using `#pragma HLS DATAFLOW`. The dataflow pragma enables task-level pipelining between load, compute, and store functions.

Since there's only one tile (the entire array), I'll restructure to use `#pragma HLS DATAFLOW` with proper ping-pong double buffers, where load/compute/store can be overlapped at the task level.

```cpp
#include "jacobi-2d.h"
#include <string.h>

static void load(int buf_sel,
                 double lA0[N][N], double lB0[N][N],
                 double lA1[N][N], double lB1[N][N],
                 double A[N][N], double B[N][N]) {
    const int n = N;
    if (buf_sel == 0) {
        load_A_rows_0:
        for (int i = 0; i < n; i++) {
            load_A_cols_0:
            for (int j = 0; j < n; j++) {
#pragma HLS PIPELINE II=1
                lA0[i][j] = A[i][j];
            }
        }
        load_B_rows_0:
        for (int i = 0; i < n; i++) {
            load_B_cols_0:
            for (int j = 0; j < n; j++) {
#pragma HLS PIPELINE II=1
                lB0[i][j] = B[i][j];
            }
        }
    } else {
        load_A_rows_1:
        for (int i = 0; i < n; i++) {
            load_A_cols_1:
            for (int j = 0; j < n; j++) {
#pragma HLS PIPELINE II=1
                lA1[i][j] = A[i][j];
            }
        }
        load_B_rows_1:
        for (int i = 0; i < n; i++) {
            load_B_cols_1:
            for (int j = 0; j < n; j++) {
#pragma HLS PIPELINE II=1
                lB1[i][j] = B[i][j];
            }
        }
    }
}

static void compute(int buf_sel,
                    double lA0[N][N], double lB0[N][N],
                    double lA1[N][N], double lB1[N][N]) {
    const int n = N;
    const int tsteps = TSTEPS;
    const int TILE_ROWS = 16;

    double (*lA)[N] = (buf_sel == 0) ? lA0 : lA1;
    double (*lB)[N] = (buf_sel == 0) ? lB0 : lB1;

    for (int t = 0; t < tsteps; t++) {
        // A -> B stencil, processed in row tiles
        stencil_AB_tile:
        for (int ti = 1; ti < n - 1; ti += TILE_ROWS) {
#pragma HLS LOOP_TRIPCOUNT min=6 max=6
            int i_end = (ti + TILE_ROWS < n - 1) ? ti + TILE_ROWS : n - 1;
            stencil_AB_outer:
            for (int i = ti; i < i_end; i++) {
#pragma HLS LOOP_TRIPCOUNT min=1 max=16
                stencil_AB_inner:
                for (int j = 1; j < n - 1; j++) {
#pragma HLS PIPELINE II=1
#pragma HLS UNROLL factor=4
#pragma HLS DEPENDENCE variable=lA0 inter false
#pragma HLS DEPENDENCE variable=lB0 inter false
#pragma HLS DEPENDENCE variable=lA1 inter false
#pragma HLS DEPENDENCE variable=lB1 inter false
#pragma HLS LOOP_TRIPCOUNT min=88 max=88
                    lB[i][j] = 0.2 * (lA[i][j] + lA[i][j-1] + lA[i][j+1]
                                     + lA[i+1][j] + lA[i-1][j]);
                }
            }
        }

        // B -> A stencil, processed in row tiles
        stencil_BA_tile:
        for (int ti = 1; ti < n - 1; ti += TILE_ROWS) {
#pragma HLS LOOP_TRIPCOUNT min=6 max=6
            int i_end = (ti + TILE_ROWS < n - 1) ? ti + TILE_ROWS : n - 1;
            stencil_BA_outer:
            for (int i = ti; i < i_end; i++) {
#pragma HLS LOOP_TRIPCOUNT min=1 max=16
                stencil_BA_inner:
                for (int j = 1; j < n - 1; j++) {
#pragma HLS PIPELINE II=1
#pragma HLS UNROLL factor=4
#pragma HLS DEPENDENCE variable=lB0 inter false
#pragma HLS DEPENDENCE variable=lA0 inter false
#pragma HLS DEPENDENCE variable=lB1 inter false
