#define WIDE_BUS_WIDTH 512
#define DOUBLES_PER_BEAT 8  // 512 / 64

typedef ap_uint<WIDE_BUS_WIDTH> wide_bus_t;

// Helper: read N*N doubles from wide bus into flat double array
static void wide_bus_read_double(double *dst, wide_bus_t *src, int n_elem) {
    int n_beats = (n_elem + DOUBLES_PER_BEAT - 1) / DOUBLES_PER_BEAT;
    read_loop:
    for (int b = 0; b < n_beats; b++) {
#pragma HLS PIPELINE II=1
        wide_bus_t word = src[b];
        for (int k = 0; k < DOUBLES_PER_BEAT; k++) {
#pragma HLS UNROLL
            int idx = b * DOUBLES_PER_BEAT + k;
            if (idx < n_elem) {
                ap_uint<64> bits = word.range(64*(k+1)-1, 64*k);
                double val;
                memcpy(&val, &bits, sizeof(double));
                dst[idx] = val;
            }
        }
    }
}

